PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE datasets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    category TEXT,
    species_key TEXT,
    species_name TEXT,
    study TEXT,
    condition TEXT,
    meta2d_path TEXT,
    processed_path TEXT,
    original_path TEXT,
    description TEXT
);
DELETE FROM sqlite_sequence;
COMMIT;
